 {popup.type==='reviewOnboarding'&&<><Field label="Review outcome"><select name="status"><option>Correction</option><option>Approved</option></select></Field><Field label="Review evidence / corrections"><textarea name="note" required rows={4}/></Field><p className="h-note">Approval requires an employee-submitted checklist, joining document, declaration and acknowledgement of current approved policies.</p></>}
