 {popup.type==='policy'&&<><Field label="Policy title"><input name="title" defaultValue={popup.item?.title||''} required/></Field><Field label="New version"><input name="version" defaultValue={popup.item?'1.1':'1.0'} required/></Field><Field label="Company applicability">{companySelect(popup.item?.company)}</Field><Field label="Country applicability"><select name="country" defaultValue={popup.item?.country||'All'}>{['All','India','UAE','Other'].map(c=><option key={c}>{c}</option>)}</select></Field><Field label="Full policy text"><textarea name="content" rows={12} defaultValue={popup.item?.content||''} maxLength={15000} required/></Field><Field label="Status"><select name="status"><option>Draft</option><option>Approved</option></select></Field><label className="h-check-label"><input type="checkbox" name="confirm"/>If approving, I confirm the applicable HR, management and jurisdiction review is complete.</label></>}
